) AS (
  VALUES 
    (393::BIGINT, 'Simplemente es un mal profesor, recomiendo evadirlo hasta donde sea posible, cuando explica lo hace bien pero pierde todo el tiempo de la clase hablando paja y explica las cosas a la carrera cuando podría simplemente ponerse a dar materia bien, califica 100% binario, el procedimiento no importa.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2026-04-13T00:00:00+00:00'::TIMESTAMPTZ, '38fb0bfed70f0cdf6246448845447bf4a79aedd2f52cccc795b7e51d2886a46c'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'eff2663a0f7af54329b5f31696a1fccb3545629dc4b4e5c05c58369b84d6b722'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'A veces se va un poco por las ramas explicando, pero tiene una forma clara de explicar algunos temas difíciles, deja tareas fáciles, es amable en las horas de consulta y hace que el curso sea llevadero y más sencillo de pasar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '18f1c5e91e205cc965e9fd3ca486ec3560f19ac0d7e7d91c69fc83eb7f57f486'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'El profesor le gusta explicar pero no hace ejercicios del tema y explica lo mas basico, hay que estudiar por apatre porque los examenes nada que ver con lo que el enseña en clase, examenes dificiles y califica binario algo bueno es que regala puntos extra en examenes o trabajos a final del curso'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Da crédito extra']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '81abbe763e90700025110f90790a16e0cad6c901d55eb7cd2c701da230e5ba18'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Explica bien, digamos que es un buen profe, cumple, pero es bastante desorganizado con las fechas, los examenes son bastante duros pero intenta ayudar dando credito extra en examenes o asi, pero aun asi es bastante dificil aprobar con el'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '76403fd008bd1934d8d5eb4698827598e8635fc38b70906014d2bdd6a6097152'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Por los comentarios tuve miedo al inicio pero luego a lo largo del semestre el profe es vacilón. Suele hacer 4 quices, 4 exámenes y 4 tareas. La asistencia a la clase la evalúa. Los exámenes suelen ser muy parecidos a lo que él explica, no es nada que nunca se vio.En los exámenes/quices es estricto.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-10-23T00:00:00+00:00'::TIMESTAMPTZ, '6a3d6b02d8453d062953125cedee3186310840fc7b8140ac467d0591075588ee'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'El curso es aburridísimo. El profe dejó todo para último momento entonces la retroalimentación que da no sirve de nada.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '337a87dc638854530be98db62dec9e62481188f882680b363a04ddd4327e9e72'::TEXT, ARRAY[1329]::BIGINT[]),
    (393::BIGINT, 'Llegué con miedo al curso por todos los malos comentarios. Sin embargo, es totalmente lo contrario a lo que dicen. Explica super bien, ayuda demasiado, solo es muy estricto y le gusta que le pongan atención. Pero es un excelente profesor, volvería a llevar el curso con él mil veces.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8d13061cc92b6e1f7617824157b86dc21b371236b294413ab9178fbe84d27304'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Es muy complicado, sólo lo que él dice es la verdad, no le contradiga, se molesta demasiado, si puede evitarlo mejor, su trato es muy malo, parece frustrado, habla de los profesores y presume de su experiencia. No matricule con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bc14e0eed1420a0823bb787b33271a2ec6d0c7a620618192519f0a58673d1623'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'El profesor carece de habilidades docentes, dificultando el aprendizaje. No ofrece claridad en las explicaciones, muestra poco interés en resolver dudas y tiende a humillar a los estudiantes. No proporciona retroalimentación en el curso. Si desea aprender NO matricule con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9d7fff12da2beedbaac6206050f28ddd6edb51c4c256fc85a809c8592bbaa0aa'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Fatal, bastante complicado como persona, como profesional no se sabe, siempre ha dado clases, no le pregunte nada, sólo diga que sí, evitelo, solo asista a lecciones y no le contradiga.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a3348b86f63909e298818b8d6300f3381a64648dafb657df5e7dc1ffaa089d97'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Su esposa trabaja en el Tec, es la abogada de la institución, su elección como director fue dudosa, no hubieron elecciones. El rector que lo nombró salió cuestionado por fuertes anomalías en el Tec. En fin,un funcionario público de muy bajo nivel que vive de la política. Un frustrado más'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-05-07T00:00:00+00:00'::TIMESTAMPTZ, '9d35babb54c9d64851f65f244713b3ac8051fe05749946620499c917f875653c'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Hace comentarios de otros profesores, cuenta historias de sus supuestas experiencias en los trabajos, lo raro es que siempre a sido profesor. Más bien parece frustrado. Lo recomendable es no decir nada y sólo asistir a la supuesta clase, y para las próximas elecciones. Que se pensione el mediocre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-04-07T00:00:00+00:00'::TIMESTAMPTZ, '8cf62ed980bf9261fe544f0abdcaf97b483e7b6d1d35d655bb77e6a8eda211b5'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Pedazo de mierda, increíble que una persona así tenga trabajo, el tec y su rectoría de mierda debería despedirlo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-12T00:00:00+00:00'::TIMESTAMPTZ, 'e52de85367b2227bda114f5245816d5169c0b53fc0b2b9b2d4740a9d211e74d8'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Está deteriorando la escuela con sus desiciones, No sabe trabajar, se equivoca y no sabe donde está parado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, '8e1956bf2ff27f1035c3948ecdd5ec06da4b172f282c37633761e960105e23f9'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Es decepcionante ver un sistema educativo con profesores frustrados sin capacidad, un señor ignorante que carece de conocimiento y educación, es un nivel de aprendizaje bastante bajo, hay que esperar que la nueva rectoría ponga límites a muchos profesores de muy bajo nivel'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-12-23T00:00:00+00:00'::TIMESTAMPTZ, '338ed3d1c890404883e56f98bcfd3920147c4a2af8b20adec82c0566f5b9f740'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Irrespetuoso con las personas. Lamentablemente no se realizó votaciones para nombrarlo como director, lo pusieron a dedo de parte del amigo rector. Son puestos políticos nombrados NO por talento, sino por amiguismo. Eso habla muy mal de el sistema educativo. Fatal nuestro país'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-09-21T00:00:00+00:00'::TIMESTAMPTZ, '7ca57989352b6dda258d0a29e855a312dede903cebeecf4d22ccc4ae6efa3644'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'No tiene capacidad como docente. Es demasiado egocentrico, solamente él tiene la razón y si se le contradice se molesta. El problema es que son personas que están por el salario. En el sector privado no trabajarían nunca, mucho menos capacidad de generar empresa, solo del erario público puede vivir'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c161dd5211036659f9b8427e6525648e4d8cf3c045b84b0cfbb63066f06d79ee'::TEXT, ARRAY[281, 89, 4925]::BIGINT[]),
    (393::BIGINT, 'Este señor es el ser más irrespetuoso que existe. Es un holgazán. Además se cree una autoridad intelectual. Si uno realiza una búsqueda rápida en internet visualiza lo nefasto que es el sistema público en ocasiones, manteniendo a personas como este señor en el sistema sin publicaciones ni doctorado.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-22T00:00:00+00:00'::TIMESTAMPTZ, '12e97cad07378ab945a9e18d8c9f787b9ab424e69e1b6304e52f482bcaa4ee13'::TEXT, ARRAY[1358]::BIGINT[]),
    (393::BIGINT, 'Existencia de programa computacional para la trazabilidad de la información en donde se califica al empleado público y, se genere un registro histórico y público para dar seguimiento a los empleados y la calidad de servicio que brindan. Así, puede ser evaluado por profesionales jurídicos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '2e5fd5007e412b84f1c494db86e99263a6ede3506a0351d04658c15352076b8f'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Si un funcionario público agrede a un ciudadano costarricense, estaría cometiendo una falta grave. Por ello, se deben organizar todas las personas que lo hallan vivido e ir a la fiscalía más cercana con asesoría jurídica, así hacer oficial una demanda. Y, enterar al país de lo acontecido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1bef85675cf9332e58bc363108d5a054ee7e58c908800507a5081d6242c2a0f3'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Profesor irresponsable con el curso, difícil de tratar casi un Rivas 2.0.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '2e3647275dbd561109529d59b807c31b4068ba870b4f80df4c014be16fadeec6'::TEXT, ARRAY[1358]::BIGINT[]),
    (393::BIGINT, 'Se dice que nunca trabajó en el mercado laboral o casi nada. Osea, solamente de profesor a vívido. Una persona así no tiene experiencia. Por cierto, acostumbra a tratar mal al estudiante. Se deben denunciar ese tipo de profesores. No se dejen intimidar'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '33b4d9fa101ce601a98a06ec8645cff8a3870885e3788b29d86c9010882d3d94'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Fácilmente lo peor de la escuela de electrónica, si pueden evitarlo es lo mejor, su palabra es definitiva aunque se equivoque, increíblemente necio y terco.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2019-11-30T00:00:00+00:00'::TIMESTAMPTZ, '56fc4906a23bd4330b399f9e07e53d19698937ffa0b85ae2b8ca271ae1ae256d'::TEXT, ARRAY[1424]::BIGINT[]),
    (393::BIGINT, 'Explica bastante bien, aunque la asistencia no es obligatoria lo mejor es faltar lo menor posible, se preocupa por que se genere un anteproyecto bien formulado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-07-16T00:00:00+00:00'::TIMESTAMPTZ, '96688e7bc377b51be47b61cbe8e0abe3fccfdd5e7c84fb13815d5d87752a800c'::TEXT, ARRAY[1329]::BIGINT[]),
    (393::BIGINT, 'Es durisimo, explica relativamente bien, pero hayq eu estudiar mucho po cuenta de uno para poder pasar el curso. Califica a matar, olvidas un menos y te pone un cero en el examen, yo pase a la primera pero poniendole un esfuerzo tremendo, aprende pero sufre.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '23729128525b626cac8df70975230e61ae0345b61ed85ad9c92082e8daebbe39'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Es estricto, pero explica bien , solo haga lo que el dice y todo va a salir bien'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5dfc299f77f4e7b62d2b949f754254da5b0c9e3b4785503e197976016127bc2a'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'El mejor Ingeniero jamas visto en la escuela(entiéndase el sarcasmo), si le ponés "tempera blanca" no te toma en cuenta. Solo explica con transparencias(diapositivas). Lo recomiendo a los primeros ingreso para que se resbalen con los cortos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'da83e2ff8812adb36108e19534626f19cbca433e147ebf0b12d8cc8a4139518c'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Si quiere aprender teoria metalo con el, pero si quiere aprender a solucionar circuitos complicados no lo tome en cuenta. Califica muy duro, nunca contesta correos ni lo atiende, y da las notas cuando le da la gana, por ejemplo a nosotros nos indico de un dia para otro quienes iban a reposicion'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-20T00:00:00+00:00'::TIMESTAMPTZ, '69c2ee570348c37e16da3c32c632a747e2c73524e9b74099eede542fe788d930'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Arquitecto frustrado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4c372b2e6dbff970299f61362d65231a31907527305e8e965748f25916b18f67'::TEXT, ARRAY[1424]::BIGINT[]),
    (393::BIGINT, 'Es el que hace los ejercicios imposibles en cada examen, no tiene piedad a la hora de poner trampas y es muy desinteresado con el estudiante. Con costos le pasa nadie y luego juega de que no es culpa de el.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5fa36224d36538ec3b596df6c640e1c13c0c29452a639f42b8a1781878ce8f43'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Una sola palabra: pésimo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '6e6f923b513fd39ee5d91a58d30c7710bf5b78b7d405ca43259205d26f3101c3'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Muy dolor, jode por todo, baja puntos por comas y cosas por el estilo, lo escogería solo si es el único o si es el menos malo'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a35998ea5c0fa5d1b3f8d3f23cb4059f27b80b08466444084c90d64edbbb5550'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-16T00:00:00+00:00'::TIMESTAMPTZ, '8e59617036c308b8a9a7a804e60b8d05593fa237c765d4b98518ac157973ac46'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Un payaso de primera y un maldito.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '505ff564be0f649682e721b95bf65d7a9a653077c0746e088af16368e0b471c4'::TEXT, ARRAY[927]::BIGINT[]),
    (393::BIGINT, 'Muy exigente en exámenes y siempre atrasado en la materia por lo que casi nunca se hacen ejercicios'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '2f790a3fa27258795c5ab0684a1828393ed8c524385e8b7847b86568e7e0eac5'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Profesor estilo karaoke'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5a373de6b221dea810d40f3654f350aa2c963887658c1c0ba05c42bab98d6cbf'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, '¿Cómo van a recomendar a Miguel? Es de los peores profes con el que he estado. En clases nunca explicó nada, solo se subió a un podio a narrar diapositivas con los ejercicios resueltos (dicho sea de paso, son los ejercicios más fáciles de cada tema), en exámenes rudísimo, jamás con Miguel.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '38103a13b25ac51bc7159159d42068f5a9eaa34423142d5ec441c0b361c946bc'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Explica muy bien, pero es muy exigente en los exámenes, pidiendo paso a paso (explicando) la solución.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '69c1eedf9d8d1e0ed5186ca1bd27512e7120fbf3a0c86c0e4e0bf957c8c1c130'::TEXT, ARRAY[1257]::BIGINT[]),
    (393::BIGINT, 'Es exigente pero buen Profe'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f399e25626b6b7980b3f7dbf42f63475e02d143f5cd271f5367a2d57acff96d9'::TEXT, ARRAY[927]::BIGINT[]),
    (393::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '493da976a4821fd3b0bd0e70c763ca645c76fbaf81e58120e4199f02d7ae5540'::TEXT, ARRAY[1257]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
